function check(bool $v,string $why):void{if(!$v)throw new RuntimeException($why);}
function sc(int $id,string $ukid,string $owner,int $row,int $col):CardInstance{global $defs;$d=$defs[$ukid];return new CardInstance(instanceId:$id,ukid:$ukid,owner:$owner,zone:'field',row:$row,col:$col,hp:(int)$d['health'],hpMax:(int)$d['health'],move:(int)$d['move'],moveMax:(int)$d['move'],strikeWeak:(int)$d['strike_weak'],strikeMedium:(int)$d['strike_medium'],strikeStrong:(int)$d['strike_strong'],prop:json_decode($d['prop']??'{}',true)?:[]);}
function seed(string $ukid='s1_17',int $distance=2):GameState{$s=new GameState(91,101,202);$s->status='battle';$s->battle=['active'=>'host','turn'=>1,'strike'=>null];$s->addCard(sc(1,$ukid,'host',3,3));$s->addCard(sc(2,'s1_128','player',3+$distance,3));$s->addCard(sc(3,'s1_1','host',1,1));$s->addCard(sc(4,'s1_1','player',6,5));return$s;}
function cmd(GameState $s,string $actor,string $type,array $p=[]):mixed{$r=(new Engine(clock:fn()=>1800000000))->apply($s,$actor,new Command($type,$p));check($r->success,$type.': '.($r->error??''));return$r;}
function es(array $events,string $type):array{return array_values(array_filter($events,fn($e)=>$e['type']===$type));}
$results=[];$examples=[];
function pair(string $name,GameState $seed,Closure $run,Closure $verify,string $queue='4,6,2,5,3,1'):void{
 global $defs,$results,$examples;$out=[];
 foreach([false,true]as$observed){$_SESSION=['debug_roll'=>$queue];Dice::init();$s=GameState::fromArray($seed->toArray());$rec=$observed?new Recorder(91,1,[],[],true,fn($c)=>$defs[$c->ukid]['name']??null):null;$s->historyRecorder=$rec;$r=$run($s);$out[]=[$s->toArray(),serialize($r),Dice::remaining()];if($rec){$events=$rec->batch($s)->data()['events'];$verify($events,$s);if(true)$examples[$name]['structured']=array_map(fn($e)=>array_intersect_key($e,array_flip(['type','host','player'])),array_values(array_filter($events,fn($e)=>preg_match('/^(coins|modifier|marker|status|trait|instant|capability|characteristic|cell_marker)\./',$e['type']))));foreach(['host','player']as$view){$lines=[];foreach($events as$e)if($e[$view]!==null&&($t=JournalText::format($e['type'],$e[$view],$view))!==null)$lines[]=$t;$examples[$name][$view]=$lines;}}}
 check($out[0]===$out[1],$name.' changed DTO, result or RNG');$results[]=$name;
}
function attackChecks(array $events,string $type):void{check(count(es($events,'attack.declared'))===1,'declaration once '.$type);$r=es($events,'attack.result');check(count($r)===1&&$r[0]['payload']['attack_type']===$type,'result once '.$type);check(count(es($events,'dice.rolled'))===1,'one real die '.$type);check(count(es($events,'dice.final'))===1,'one final die '.$type);$order=array_column($events,'type');check(array_search('attack.declared',$order)<array_search('dice.rolled',$order)&&array_search('dice.rolled',$order)<array_search('dice.final',$order)&&array_search('dice.final',$order)<array_search('attack.result',$order),'declaration / roll / final / result order '.$type);foreach($events as$e)if(preg_match('/^(coins|modifier|marker|status|trait|instant|capability|characteristic|cell_marker)\./',$e['type']))check(!isset($e['payload']['defend']),'no artificial defender');}

function observe(GameState $s,Closure $f):mixed{$s->historyRecorder?->commandStarted($s,'host',new Command('fixture'));$r=$f($s);$s->historyRecorder?->commandFinished($s,\Berserk\Core\Result::ok());return$r;}
